// demo/deck: the site is a keynote. Full-screen slides, one idea each; the tour slides play the product in a window.
//
//   advance   → ↓ space PageDown Enter, a click (the left third goes back), a swipe, a scroll tick
//   back      ← ↑ PageUp Backspace          Home / End: first / last
//   G         all slides (also a pinch, or ⌃ + scroll on a trackpad); click one to go there, Esc to leave
//   P         play as a talk: each slide stays up for its data-dur, then moves on, with the progress line
//   #4        opens on slide 4
//   ?record&ratio=16:9|1:1|9:16   the deck played as a talk, once, for Monet Shot
//   ?t=20     that moment of the talk, frozen       ?slide=4&t=3   slide 4, 3 s after it arrived, frozen
//
// Every frame is a function of (slide, seconds since it arrived, overview amount), so the talk, the record stage
// and a frozen ?t= all draw through the same draw().
import { Tour, recordStage, pause, include } from '../tour/tour.js';
import script from './script.js';

const TR = .8;          // a transition, in seconds
const LEAD = .65;       // a tour slide's film starts this long after the slide arrives (plus the film's own .25 s beat)
const BUILD = .7;       // how long a data-build element takes to fade up
const cl = (x) => (x < 0 ? 0 : x > 1 ? 1 : x);
const sm = (t) => t * t * t * (t * (t * 6 - 15) + 10);
const lerp = (a, b, t) => a + (b - a) * t;
const NN = (n) => String(n).padStart(2, '0');

// harvested screens (<div data-tour-include="…">) load first, then the format starts
export default function init(root) {
  let stop = null, dead = false;
  include(root).then(() => { if (!dead) stop = boot(root); });
  return () => { dead = true; stop?.(); };
}

function boot(root) {
  const q = new URLSearchParams(location.search), rec = q.has('record');
  const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
  const fixT = q.get('t') != null ? +q.get('t') : null;
  const slides = [...root.querySelectorAll('.deck-slide')], N = slides.length;
  const bar = root.querySelector('.deck-bar'), prog = root.querySelector('.deck-progress b');
  const countI = root.querySelector('.deck-i'), countOf = root.querySelector('.deck-of');
  let alive = true, raf = 0;
  const off = [];
  const on = (el, ev, fn, o) => { if (!el) return; el.addEventListener(ev, fn, o); off.push(() => el.removeEventListener(ev, fn, o)); };
  if (countOf) countOf.textContent = NN(N);

  // the box: the screen on the page, the ratio's box in ?record
  const box = rec ? recordStage(root, q) : null;
  const D = { W: 0, H: 0, su: 9 };
  const shape = () => {
    D.W = box ? box.w : root.clientWidth || innerWidth; D.H = box ? box.h : root.clientHeight || innerHeight;
    const a = D.W / D.H; D.su = Math.min(D.W, D.H) / 100;
    root.classList.toggle('is-wide', a >= 1.2); root.classList.toggle('is-square', a < 1.2 && a >= .8); root.classList.toggle('is-tall', a < .8);
    root.style.setProperty('--su', D.su + 'px');
  };
  shape(); on(window, 'resize', () => { shape(); dirty = true; });

  // the tour slides: each window gets a copy of the product and its own film
  const tpl = root.querySelector('template.deck-product')?.content;
  const films = slides.map((s) => {
    const film = s.querySelector('.deck-film'); if (!film) return null;
    const w = film.querySelector('[data-tour-window]');
    if (w && !w.firstElementChild && tpl) w.append(tpl.cloneNode(true));
    const f = script.films[+s.dataset.film || 0] || { steps: [] };
    const S = { size: script.size, enter: f.enter || script.enter, pointer: script.pointer, intro: 0, settle: .3, outro: .2, still: f.still,
      steps: [...(f.start || []).map((st) => ({ ...st, at: 0 })), pause(.25), ...f.steps] };
    return new Tour(film, S, { driver: 'manual', record: 'page', captions: 'off' });
  });
  const builds = slides.map((s) => [...s.querySelectorAll('[data-build]')].map((el) => ({ el, d: +el.dataset.build || 0 })));
  const dur = slides.map((s, i) => (s.dataset.dur ? +s.dataset.dur : films[i] ? LEAD + films[i].duration + 1.1 : 5));
  const starts = dur.reduce((a, d, i) => (a.push(i ? a[i - 1] + dur[i - 1] : 0), a), []);
  const TOTAL = starts[N - 1] + dur[N - 1];

  // ── one frame ──
  const cache = new WeakMap();
  const put = (el, k, v) => { let c = cache.get(el); if (!c) cache.set(el, (c = {})); if (c[k] !== v) { c[k] = v; if (k[0] === '-') el.style.setProperty(k, v); else el.style[k] = v; } };
  function grid() {      // where each slide sits in the overview
    const { W, H, su } = D, cols = W / H >= 1.2 ? 4 : 3, rows = Math.ceil(N / cols), gap = su * 1.8;
    const top = su * 7, AW = W - su * 10, AH = H - top - su * 9;
    const s = Math.min((AW - (cols - 1) * gap) / cols / W, (AH - (rows - 1) * gap) / rows / H);
    const cw = W * s, ch = H * s, x0 = (W - (cols * cw + (cols - 1) * gap)) / 2, y0 = top + (AH - (rows * ch + (rows - 1) * gap)) / 2;
    return slides.map((_, i) => ({ x: x0 + (i % cols) * (cw + gap), y: y0 + Math.floor(i / cols) * (ch + gap), s }));
  }
  function draw(cur, prev, local, dir, ov, talkT) {
    const raw = reduce || cur === prev ? 1 : cl(local / TR), p = sm(raw), G = ov > 0 ? grid() : null, { W, H } = D;
    const pin = sm(cl((raw - .3) / .7)), pout = sm(cl(raw / .6));     // the old slide clears before the new one settles in
    root.style.setProperty('--ov', ov.toFixed(3));
    root.classList.toggle('is-ov', ov > .5);
    slides.forEach((s, i) => {
      const kind = s.dataset.enter || 'fade';
      let o = 0, x = 0, k = 1;
      if (i === cur) { o = pin; if (kind === 'scale') k = 1.035 - .035 * p; if (kind === 'push') x = dir * (1 - p) * .06; }
      else if (i === prev && p < 1) { o = 1 - pout; if (kind === 'scale' || slides[cur].dataset.enter === 'scale') k = 1 - .02 * p; if (slides[cur].dataset.enter === 'push') x = -dir * p * .06; }
      let X = x * W + (1 - k) * W / 2, Y = (1 - k) * H / 2;
      if (G) { const g = G[i], e = sm(ov); X = lerp(X, g.x, e); Y = lerp(Y, g.y, e); k = lerp(k, g.s, e); o = lerp(o, 1, e); }
      put(s, 'transform', X || Y || k !== 1 ? `translate(${X.toFixed(2)}px,${Y.toFixed(2)}px) scale(${k.toFixed(5)})` : '');
      put(s, 'opacity', o.toFixed(3));
      put(s, 'visibility', o < .002 ? 'hidden' : 'visible');
      s.classList.toggle('is-cur', i === cur);
      s.setAttribute('aria-hidden', i === cur ? 'false' : 'true');
      // builds: the current slide's from its own clock; every other slide shows them done
      const lt = i === cur && !reduce ? local : 1e3;
      for (const b of builds[i]) put(b.el, '--in', sm(cl((lt - b.d) / BUILD)).toFixed(3));
      // films: the current one plays from its own clock, the rest rest on their still frame
      const t = films[i]; if (!t) return;
      if (i === cur && !reduce) t.render(Math.max(0, local - LEAD));
      else if (i !== prev || p >= 1) t.render(i === cur || ov > 0 || reduce ? t.stillAt : 0);
    });
    if (countI) countI.textContent = NN(cur + 1);
    const pr = talkT != null ? talkT / TOTAL : N > 1 ? cur / (N - 1) : 1;
    if (prog) put(prog, 'transform', `scaleX(${cl(pr).toFixed(4)})`);
  }
  // the talk as a function of one number
  const talkAt = (T) => { T = Math.max(0, Math.min(TOTAL, T)); let i = 0; while (i < N - 1 && starts[i + 1] <= T) i++; return { cur: i, prev: Math.max(0, i - 1), local: T - starts[i], T }; };
  const ready = Promise.all(films.filter(Boolean).map((t) => t.api.ready));

  // ── ?record: the talk, once ──
  if (rec) {
    const frame = (T) => { const s = talkAt(T); draw(s.cur, s.cur ? s.prev : 0, s.cur ? s.local : 1e3, 1, 0, s.T); };
    window.deck = { seek: (t) => { stopRec = true; frame(+t); }, duration: TOTAL, slides: N };
    let stopRec = false;
    ready.then(() => {
      if (!alive) return;
      if (fixT != null) return frame(fixT);
      frame(0);
      setTimeout(() => { const s0 = performance.now(); const loop = (now) => { if (!alive || stopRec) return; const T = (now - s0) / 1000; frame(T); if (T < TOTAL) raf = requestAnimationFrame(loop); }; raf = requestAnimationFrame(loop); }, (+q.get('hold') || 1.2) * 1000);
    });
    return () => { alive = false; cancelAnimationFrame(raf); off.forEach((f) => f()); films.forEach((t) => t?.destroy()); };
  }

  // ── the page ──
  const st = { cur: 0, prev: 0, at: performance.now() - 1e6, dir: 1, ov: 0, ovFrom: 0, ovTo: 0, ovAt: 0, talk: false, frozen: null };
  let dirty = true;
  const fromHash = () => { const n = parseInt(location.hash.slice(1), 10); return n >= 1 && n <= N ? n - 1 : null; };
  const h0 = fromHash(); if (h0 != null) st.cur = st.prev = h0;
  const setOv = (v) => { if (st.ovTo === v) return; st.ovFrom = st.ov; st.ovTo = v; st.ovAt = performance.now(); if (v) setTalk(false); dirty = true; };
  const go = (i, dir) => {
    i = Math.max(0, Math.min(N - 1, i)); if (i === st.cur) return;
    st.prev = st.cur; st.cur = i; st.dir = dir ?? (i > st.prev ? 1 : -1); st.at = performance.now(); dirty = true;
    try { history.replaceState(null, '', '#' + (i + 1)); } catch (e) {}
  };
  const next = () => (st.ovTo ? null : go(st.cur + 1)), back = () => (st.ovTo ? null : go(st.cur - 1));
  const playBtn = root.querySelector('.deck-play');
  function setTalk(v) {
    st.talk = v; root.classList.toggle('is-talk', v);
    playBtn?.setAttribute('aria-label', v ? 'Pause the talk' : 'Play as a talk');
    const l = playBtn?.querySelector('span'); if (l) l.textContent = v ? 'Pause' : 'Play talk';
    if (v && st.cur === N - 1) { st.prev = st.cur; st.cur = 0; st.dir = 1; st.at = performance.now(); }
    else if (v) st.at = performance.now() - Math.min((performance.now() - st.at), 1e3 * dur[st.cur] * .5);   // carry on from about here
    dirty = true;
  }

  const loop = (now) => {
    if (!alive) return;
    const local = (now - st.at) / 1000;
    if (st.talk && local >= dur[st.cur]) { if (st.cur < N - 1) go(st.cur + 1, 1); else setTalk(false); }
    const ovP = cl((now - st.ovAt) / 450); st.ov = lerp(st.ovFrom, st.ovTo, sm(ovP));
    const busy = dirty || ovP < 1 || local < 12 + LEAD + (films[st.cur]?.duration || 0) || st.talk;
    if (busy) {
      dirty = false;
      draw(st.cur, st.prev, (now - st.at) / 1000, st.dir, st.ov, st.talk ? starts[st.cur] + Math.min((now - st.at) / 1000, dur[st.cur]) : null);
    }
    raf = requestAnimationFrame(loop);
  };

  ready.then(() => {
    if (!alive) return;
    if (fixT != null) {       // frozen: a moment of the talk, or of one slide
      const sl = q.get('slide');
      if (sl != null) { const i = Math.max(1, Math.min(N, +sl)) - 1; draw(i, i, fixT, 1, 0, null); }
      else { const s = talkAt(fixT); draw(s.cur, s.cur ? s.prev : 0, s.cur ? s.local : 1e3, 1, 0, s.T); }
      return;
    }
    st.at = performance.now() - (h0 != null ? 0 : 0);
    raf = requestAnimationFrame(loop);
  });

  // ── input ──
  const NEXT = new Set(['ArrowRight', 'ArrowDown', 'PageDown', ' ', 'Enter']), BACK = new Set(['ArrowLeft', 'ArrowUp', 'PageUp', 'Backspace']);
  on(window, 'keydown', (e) => {
    if (e.metaKey || e.ctrlKey || e.altKey || e.target.closest?.('input, textarea, select, [contenteditable]')) return;
    if (e.key === 'Enter' && e.target.closest?.('a, button')) return;
    if (e.key === ' ' && e.target.closest?.('button')) return;
    const k = e.key.length === 1 ? e.key.toLowerCase() : e.key;
    if (NEXT.has(e.key)) { e.preventDefault(); next(); }
    else if (BACK.has(e.key)) { e.preventDefault(); back(); }
    else if (k === 'Home') { e.preventDefault(); go(0); }
    else if (k === 'End') { e.preventDefault(); go(N - 1); }
    else if (k === 'g' || k === 'o') { e.preventDefault(); setOv(st.ovTo ? 0 : 1); }
    else if (k === 'Escape') setOv(0);
    else if (k === 'p' || k === 'k') setTalk(!st.talk);
    else return;
    wake();
  });
  on(root.querySelector('.deck-stage'), 'click', (e) => {
    if (e.target.closest('a, button, input, label, select')) return;
    if (st.ovTo) { const s = e.target.closest('.deck-slide'); if (s) { const i = slides.indexOf(s); setOv(0); if (i !== st.cur) { st.prev = st.cur = i; st.at = performance.now() - TR * 1000; dirty = true; try { history.replaceState(null, '', '#' + (i + 1)); } catch (er) {} } } return; }
    if (getSelection()?.toString()) return;
    const r = root.getBoundingClientRect();
    (e.clientX - r.left < r.width * .3 ? back : next)();
  });
  on(playBtn, 'click', () => setTalk(!st.talk));
  on(root.querySelector('.deck-ov'), 'click', () => setOv(st.ovTo ? 0 : 1));
  on(root.querySelector('.deck-prev'), 'click', back);
  on(root.querySelector('.deck-next'), 'click', next);
  // scroll ticks: one slide per gesture, however long the trackpad keeps coasting; ⌃ + scroll (a pinch) opens the overview
  let acc = 0, lockUntil = 0, pinch = 0;
  on(root, 'wheel', (e) => {
    e.preventDefault(); const now = performance.now();
    if (e.ctrlKey) { pinch += e.deltaY; if (pinch > 30) { setOv(1); pinch = 0; } else if (pinch < -30) { setOv(0); pinch = 0; } return; }
    if (st.ovTo) return;
    if (now < lockUntil) { lockUntil = Math.max(lockUntil, now + 260); return; }
    acc += Math.abs(e.deltaY) >= Math.abs(e.deltaX) ? e.deltaY : e.deltaX;
    if (Math.abs(acc) > 36) { (acc > 0 ? next : back)(); acc = 0; lockUntil = now + 650; }
  }, { passive: false });
  // swipes, and a two-finger pinch for the overview
  let t0 = null, d0 = 0;
  const dist = (ts) => Math.hypot(ts[0].clientX - ts[1].clientX, ts[0].clientY - ts[1].clientY);
  on(root, 'touchstart', (e) => { if (e.touches.length === 2) { d0 = dist(e.touches); t0 = null; } else if (e.touches.length === 1) t0 = { x: e.touches[0].clientX, y: e.touches[0].clientY, at: performance.now() }; }, { passive: true });
  on(root, 'touchmove', (e) => {
    if (e.touches.length === 2 && d0) { e.preventDefault(); const r = dist(e.touches) / d0; if (r < .75) { setOv(1); d0 = 0; } else if (r > 1.3) { setOv(0); d0 = 0; } }
    else if (t0 && e.cancelable) e.preventDefault();
  }, { passive: false });
  on(root, 'touchend', (e) => {
    if (!t0 || e.touches.length) return;
    const c = e.changedTouches[0], dx = c.clientX - t0.x, dy = c.clientY - t0.y; t0 = null;
    if (Math.max(Math.abs(dx), Math.abs(dy)) < 40) return;
    e.preventDefault();      // a swipe isn't also a tap
    if (Math.abs(dx) > Math.abs(dy)) (dx < 0 ? next : back)(); else (dy < 0 ? next : back)();
  });
  on(window, 'hashchange', () => { const i = fromHash(); if (i != null) go(i); });
  // the bar fades while you watch, and comes back when the pointer moves
  let idleT = 0;
  function wake() { root.classList.remove('is-idle'); clearTimeout(idleT); idleT = setTimeout(() => root.classList.add('is-idle'), 2600); }
  on(root, 'pointermove', (e) => { if (e.pointerType === 'mouse') wake(); });
  wake();

  window.deck = { go: (i) => go(i - 1), next, back, overview: (v = true) => setOv(v ? 1 : 0), talk: (v = true) => setTalk(v), duration: TOTAL, slides: N };
  return () => { alive = false; cancelAnimationFrame(raf); clearTimeout(idleT); off.forEach((f) => f()); films.forEach((t) => t?.destroy()); };
}

/* StyleFeatures scaffolds: shared runtime. Safe to load twice.
   - [data-reveal] fades in on scroll
   - .ph-video gets a play/pause button, a running timeline and a timecode, so a video slot behaves like one
     (data-dur="12" seconds, data-autoplay for background loops)
   - press N (or ?clean in the URL) to hide the notes */
if (!window.__sfScaffold) {
  window.__sfScaffold = true;
  const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
  const io = new IntersectionObserver((es) => es.forEach((e) => { if (e.isIntersecting) { e.target.classList.add('is-in'); io.unobserve(e.target); } }),
    { rootMargin: '0px 0px -8% 0px', threshold: 0.06 });
  const PLAY = '<svg viewBox="0 0 20 20" aria-hidden="true"><path d="M6 3.8v12.4L16 10z" fill="currentColor"/></svg>';
  const PAUSE = '<svg viewBox="0 0 20 20" aria-hidden="true"><path d="M5.5 4h3v12h-3zM11.5 4h3v12h-3z" fill="currentColor"/></svg>';
  const fmt = (s) => `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, '0')}`;

  function video(el) {
    if (el.__sf) return; el.__sf = true;
    const dur = +el.dataset.dur || 12, loop = el.hasAttribute('data-autoplay') || el.hasAttribute('data-loop');
    const btn = document.createElement('button');
    btn.className = 'ph-play'; btn.type = 'button'; btn.setAttribute('aria-label', 'Play video'); btn.innerHTML = PLAY;
    const bar = document.createElement('div'); bar.className = 'ph-bar'; bar.setAttribute('aria-hidden', 'true');
    bar.innerHTML = `<span class="t">0:00</span><span class="ph-track"><i></i></span><span>${fmt(dur)}</span>`;
    if (el.hasAttribute('data-nobar')) bar.hidden = true;
    if (el.hasAttribute('data-nobutton')) btn.hidden = true;
    el.append(btn, bar);
    const t = bar.querySelector('.t');
    let pos = 0, playing = false, last = 0, raf = 0, visible = true;
    const draw = () => { el.style.setProperty('--p', pos / dur); t.textContent = fmt(pos); el.style.setProperty('--sf-t', pos); };
    const tick = (now) => {
      if (!playing) return;
      pos += Math.min(.1, (now - last) / 1000); last = now;
      if (pos >= dur) { if (loop) pos = 0; else { pos = dur; set(false); } }
      draw(); el.dispatchEvent(new CustomEvent('sf:time', { detail: { t: pos, dur } }));
      if (visible) raf = requestAnimationFrame(tick);
    };
    function set(on) {
      playing = on; el.classList.toggle('is-playing', on);
      btn.innerHTML = on ? PAUSE : PLAY; btn.setAttribute('aria-label', on ? 'Pause video' : 'Play video');
      cancelAnimationFrame(raf);
      if (on) { if (pos >= dur) pos = 0; last = performance.now(); raf = requestAnimationFrame(tick); }
    }
    btn.addEventListener('click', (e) => { e.stopPropagation(); set(!playing); });
    el.sfVideo = { play: () => set(true), pause: () => set(false), seek: (s) => { pos = Math.max(0, Math.min(dur, s)); draw(); }, get t() { return pos; }, dur };
    new IntersectionObserver(([e]) => { visible = e.isIntersecting; if (visible && playing) { last = performance.now(); cancelAnimationFrame(raf); raf = requestAnimationFrame(tick); } }).observe(el);
    if (el.hasAttribute('data-autoplay') && !reduce) set(true);
    draw();
  }

  const scan = (root = document) => {
    root.querySelectorAll('[data-reveal]:not(.is-in)').forEach((el) => (reduce ? el.classList.add('is-in') : io.observe(el)));
    root.querySelectorAll('.ph-video').forEach(video);
  };
  window.sfScan = scan;
  window.sfVideo = video;
  const boot = () => scan();
  if (document.readyState === 'loading') addEventListener('DOMContentLoaded', boot); else boot();
  if (location.search.includes('clean')) document.documentElement.classList.add('sf-clean');
  if (location.search.includes('thumb')) document.documentElement.classList.add('sf-thumb');
  if (innerWidth < 700) addEventListener('DOMContentLoaded', () => document.querySelector('.sf-spec')?.classList.add('is-min'));
  addEventListener('keydown', (e) => { if (e.key === 'n' && !/INPUT|TEXTAREA/.test(document.activeElement?.tagName)) document.documentElement.classList.toggle('sf-clean'); });
  const down = () => document.documentElement.classList.toggle('is-down', scrollY > 24);
  addEventListener('scroll', down, { passive: true }); down();
}

/* tour.js: a declarative product-tour engine. The shared foundation for every StyleFeatures demo film.
   Full reference: README.md beside this file. In short:

     import { Tour, click, type, show, zoom, chapter } from './tour.js';
     new Tour(rootElement, { size: [1200, 750], steps: [ chapter('01 / 03', 'Start <em>here</em>', 'One line.'),
                                                        click('@new'), show('@modal'), type('@name', 'Hello') ] });

   Everything on screen is a pure function of one number, t (seconds). Each frame the engine works out the
   product's state at t (classes, attributes, text, CSS variables, scroll positions), the camera, the fake
   cursor and the overlays, and writes only what changed. So any moment can be rendered on its own:
   ?t=12.5 freezes there, seek(t) jumps there, and a scroll, a clock or a screen recorder can all drive it.

   Selectors ('@name' is short for [data-tour="name"]) are measured against the product as it is at the moment
   each step happens, and measured again whenever the layout changes (fonts, resize, your CSS), so editing the
   product never breaks the script. */

const cl = (x) => (x < 0 ? 0 : x > 1 ? 1 : x);
export const ease = (t) => t * t * t * (t * (t * 6 - 15) + 10);           // smootherstep: settles, no overshoot
const lerp = (a, b, t) => a + (b - a) * t;
const rnd = (n) => { const x = Math.sin(n * 91.7 + 13.1) * 43758.5453; return x - Math.floor(x); };
const sel = (s) => (typeof s === 'string' ? s.replace(/@([\w-]+)/g, '[data-tour="$1"]') : s);
const fmtTime = (s) => `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, '0')}`;

/* ── step builders ─────────────────────────────────────────────────────────────────────────────
   Pointer steps run one after another on the script's clock. Side steps (zoom, show, hide, set, tween,
   chapter, caption) start at the current moment and let the next step start with them.
   Any step takes { at: seconds } to pin it, { wait: seconds } to start later, { parallel: true }
   so a pointer step doesn't hold up the next one, { block: true } so a side step does. */
export const move = (to, o = {}) => ({ ...o, do: 'move', to });
export const click = (to, o = {}) => ({ ...o, do: 'click', to });
export const dblclick = (to, o = {}) => ({ ...o, do: 'dblclick', to });
export const hover = (to, o = {}) => ({ ...o, do: 'hover', to });
export const type = (el, text, o = {}) => ({ ...o, do: 'type', el, text });
export const drag = (handle, o = {}) => ({ ...o, do: 'drag', handle });
export const scroll = (el, to, o = {}) => ({ ...o, do: 'scroll', el, to });
export const key = (keys, o = {}) => ({ ...o, do: 'key', keys: [].concat(keys) });
export const zoom = (to, z = 'fit', o = {}) => ({ ...o, do: 'zoom', to, z });
export const unzoom = (o = {}) => ({ ...o, do: 'zoom', to: null, z: 1 });
export const show = (el, o = {}) => ({ ...o, do: 'show', el });
export const hide = (el, o = {}) => ({ ...o, do: 'hide', el });
export const set = (el, changes, o = {}) => ({ ...o, do: 'set', el, changes });
export const tween = (el, prop, from, to, o = {}) => ({ ...o, do: 'tween', el, prop, from, to });
export const chapter = (n, title, line = '', o = {}) => ({ ...o, do: 'chapter', n, title, line });
export const caption = (text, o = {}) => ({ ...o, do: 'caption', text });
export const pause = (dur = 1) => ({ do: 'pause', dur });
export const stream = (el, o = {}) => ({ ...o, do: 'stream', el });   // reveal matches one after another, like output arriving
export const tap = click;                                                 // the same step; reads better in a touch film
export const longpress = (to, o = {}) => ({ ...o, do: 'longpress', to }); // press and hold; it fires after { hold } s
export const swipe = (on, o = {}) => ({ ...o, do: 'swipe', on });         // a finger flick: { by, scroll } or { prop, from, to } (README)
export const mark = (name, o = {}) => ({ ...o, do: 'mark', name });       // a named moment: tour.api.marks[name] is its time, and the list is in order (README)

/* eases for show / hide / tween: { ease: 'out' | 'ios' | 'spring' | (t) => t }. Default: smootherstep.
   'ios' is a critically damped spring (UIKit pushes and sheets), 'spring' overshoots by about 3%. */
export const eases = {
  linear: (t) => t,
  out: (t) => 1 - Math.pow(1 - t, 3),
  ios: (t) => (t >= 1 ? 1 : (1 - (1 + 9 * t) * Math.exp(-9 * t)) / (1 - 10 * Math.exp(-9))),
  spring: (t) => (t >= 1 ? 1 : 1 - Math.exp(-6 * t) * (Math.cos(5.3 * t) + 1.13 * Math.sin(5.3 * t))),
};
const easeOf = (e) => (typeof e === 'function' ? e : eases[e] || ease);

/* when each character of a typed string lands. rhythm: undefined (even, as before) | 'human' (beats between
   words, a reach for symbols, the odd hesitation) | 'stream' (chunks, like a model's reply arriving) */
function keyTimes(txt, cps, seed, rhythm, c) {
  const at = [], b = 1 / cps;
  if (rhythm === 'stream') {
    for (let i = 0, j = 0; i < txt.length; j++) { const n = 1 + Math.floor(rnd(seed * 13 + j) * 5); c += b * n * (.5 + rnd(seed * 29 + j)); for (let m = 0; m < n && i < txt.length; m++, i++) at.push(c); }
    return at;
  }
  for (let i = 0; i < txt.length; i++) {
    let d = b * (.55 + .9 * rnd(seed * 31 + i));
    if (rhythm === 'human') {
      const ch = txt[i], pv = txt[i - 1] || '';
      if (pv === ' ') d += b * (.3 + .9 * rnd(seed * 37 + i));
      if (/[-/.:=_@|&>~"'`]/.test(ch)) d += b * .7;
      if (/[,;!?]/.test(pv) || (pv === '.' && ch === ' ')) d += b * 1.4;
      if (ch === pv && /\w/.test(ch)) d *= .6;
      if (i > 2 && rnd(seed * 43 + i) < .035) d += .2 + .25 * rnd(seed * 47 + i);
    }
    c += d; at.push(c);
  }
  return at;
}

/* load harvested fragments: <div data-tour-include="fragments/home.html"></div>. Await it before new Tour(). */
export async function include(root) {
  await Promise.all([...root.querySelectorAll('[data-tour-include]')].map(async (el) => {
    const r = await fetch(el.dataset.tourInclude); el.innerHTML = r.ok ? await r.text() : ''; el.removeAttribute('data-tour-include');
    if (!r.ok) console.warn('[tour] could not load', r.url);
  }));
}

/* ?record for a page with several tours in one frame (demo/versus, demo/deck): makes el the record stage, the box
   of ?ratio= centred on near-black with the rest of the page hidden, exactly as a single film gets it. Build each
   Tour inside it with { record: 'page' } and drive them from the page. Returns { w, h, ratio } and keeps it current. */
export function recordStage(el, q = new URLSearchParams(location.search)) {
  document.documentElement.classList.add('tour-record', 'sf-clean');
  el.setAttribute('data-tour-root', ''); el.classList.add('is-record');
  const r = (q.get('ratio') || '16:9').split(':').map(Number), box = { w: 0, h: 0, ratio: r.join(':') };
  const fit = () => {
    let w = innerWidth, h = innerHeight;
    if (r.length === 2 && r[0] > 0) { const a = r[0] / r[1]; if (w / h > a) w = Math.round(h * a); else h = Math.round(w / a); }
    box.w = w; box.h = h; el.style.setProperty('--rw', w + 'px'); el.style.setProperty('--rh', h + 'px');
  };
  fit(); addEventListener('resize', fit);
  return box;
}

const BLOCKS = new Set(['move', 'click', 'dblclick', 'hover', 'type', 'drag', 'scroll', 'key', 'pause', 'stream', 'longpress', 'swipe']);
const POINT = new Set(['move', 'click', 'dblclick', 'hover', 'drag', 'longpress', 'swipe']);

/* ── window chromes ─────────────────────────────────────────────────────────────────────────── */
const CHROME = {
  browser: (w) => `<div class="tour-chrome" data-kind="browser"><span class="tour-lights"><i></i><i></i><i></i></span>
    <span class="tour-navs"><svg viewBox="0 0 16 16"><path d="M10 3 5 8l5 5"/></svg><svg viewBox="0 0 16 16"><path d="m6 3 5 5-5 5"/></svg></span>
    <span class="tour-url"><svg viewBox="0 0 16 16"><path d="M5 7V5a3 3 0 0 1 6 0v2M4 7h8v6H4z"/></svg>${w.dataset.url || 'yourproduct.com'}</span>
    <span class="tour-navs is-end"><svg viewBox="0 0 16 16"><path d="M8 3v7M5 6l3-3 3 3M3 9v4h10V9"/></svg><svg viewBox="0 0 16 16"><path d="M8 3v10M3 8h10"/></svg></span></div>`,
  app: (w) => `<div class="tour-chrome" data-kind="app"><span class="tour-lights"><i></i><i></i><i></i></span><b>${w.dataset.title || ''}</b></div>`,
  terminal: (w) => `<div class="tour-chrome" data-kind="terminal"><span class="tour-lights"><i></i><i></i><i></i></span><b>${w.dataset.title || ''}</b></div>`,
  phone: () => `<div class="tour-chrome" data-kind="phone"><b>9:41</b><span class="tour-notch"></span><span class="tour-status"><i></i><i></i><i></i></span></div>`,
  none: () => '',
};

/* ── cursor art (hotspot at 0,0) ─────────────────────────────────────────────────────────────── */
const CURSORS = `
<svg class="tour-arrow" width="22" height="30" viewBox="-1 -1 16 23"><path d="M0 0V16.6L4.3 12.6L7.2 19.4L10 18.2L7.2 11.6H13Z" stroke-linejoin="round"/></svg>
<svg class="tour-hand" width="24" height="26" viewBox="0 0 20 22"><path d="M7 1.4c.9 0 1.6.7 1.6 1.6V9h.3V7.5c0-.8.7-1.4 1.5-1.4s1.5.6 1.5 1.4v1.9h.3V8.3c0-.8.7-1.4 1.5-1.4s1.5.6 1.5 1.4v1.5h.3v-.6c0-.8.6-1.3 1.3-1.3.8 0 1.4.6 1.4 1.3V15c0 3.4-2.5 6-5.8 6h-1.6c-2 0-3.4-.8-4.6-2.3l-4.1-5.1c-.6-.7-.5-1.7.2-2.2.7-.5 1.6-.4 2.2.2l.7.9V3c0-.9.7-1.6 1.6-1.6Z" stroke-linejoin="round"/></svg>
<svg class="tour-beam" width="10" height="24" viewBox="0 0 10 24"><path d="M2 1.5h2.2c.5 0 .8.3.8.8v19.4c0 .5-.3.8-.8.8H2M8 1.5H5.8c-.5 0-.8.3-.8.8v19.4c0 .5.3.8.8.8H8M3 12h4" fill="none" stroke-linecap="round"/></svg>`;

export class Tour {
  constructor(root, script, o = {}) {
    this.root = root; this.S = script; this.o = o; root.setAttribute('data-tour-root', '');
    const q = new URLSearchParams(location.search), d = root.dataset;
    this.q = q;
    this.reduced = matchMedia('(prefers-reduced-motion: reduce)').matches;
    this.rec = q.has('record');
    this.host = this.rec && o.record === 'page';     // { record: 'page' }: the page owns the record stage (recordStage()) and drives this tour
    this.fixT = q.get('t') != null ? +q.get('t') : null;
    this.driver = this.host ? 'manual' : this.rec ? 'record' : q.get('driver') || o.driver || d.driver || 'scroll';
    this.still = this.fixT != null || (this.reduced && !this.rec);
    const cam = q.get('camera') || o.camera || d.camera || 'on';
    this.camOn = cam !== 'off' && !(this.still && this.fixT == null);   // reduced motion: the whole window, no push-in
    const caps = q.get('captions') || o.captions || d.captions || 'record';
    this.capsOn = caps === 'always' || caps === 'on' || (caps === 'record' && this.rec);
    this.cursorOn = (q.get('cursor') || d.cursor) !== 'off';
    this.touch = (q.get('pointer') || o.pointer || d.pointer || script.pointer) === 'touch';   // a fingertip instead of the arrow
    this.loop = !this.rec && (q.has('loop') || !!o.loop || d.loop != null || !!script.loop);   // play driver: start again at the end
    root.classList.toggle('is-touch', this.touch);
    this.t = -1; this.begun = false; this.playing = false; this.frozen = false; this.alive = true;

    this.stage = root.querySelector('[data-tour-stage]');
    this.win = root.querySelector('[data-tour-window]');
    this.band = root.querySelector('[data-tour-band]');
    this.end = root.querySelector('[data-tour-end]');
    const [w, h] = (script.size || (this.win.dataset.size || '1200x750').split('x')).map(Number);
    this.Wd = w; this.Hd = h > 0 ? h : w;       // a height of 'auto' takes the shape of the data-tour-frame at each layout
    this.win.style.width = w + 'px'; this.win.style.height = this.Hd + 'px';
    const tall = script.sizeTall || this.win.dataset.sizeTall?.split('x');     // optional second design size for tall stages
    const sq = script.sizeSquare || this.win.dataset.sizeSquare?.split('x');   // optional third, for squarish stages (.8 ≤ W/H < 1.15)
    this.sizes = { wide: [w, h], tall: tall ? tall.map(Number) : null, square: sq ? sq.map(Number) : null };
    const kind = this.win.dataset.chrome || 'browser';
    if (!this.win.querySelector('.tour-chrome')) this.win.insertAdjacentHTML('afterbegin', (CHROME[kind] || CHROME.none)(this.win));
    // windows inside the window (a desk with a terminal and a browser): each [data-chrome] gets its own chrome
    for (const e of this.win.querySelectorAll('[data-chrome]')) if (!e.querySelector(':scope > .tour-chrome')) e.insertAdjacentHTML('afterbegin', (CHROME[e.dataset.chrome] || CHROME.none)(e));
    this.follow = [...this.win.querySelectorAll('[data-tour-follow]')];     // kept scrolled to their newest content
    this.grows = [...this.win.querySelectorAll('[data-tour-grow]')].reverse();   // natural height measured into --h, innermost first
    this.win.setAttribute('aria-hidden', 'true');
    this.overlays();
    this.compile();
    if (this.rec && !this.host) this.recordSetup();
    this.layout();
    this.grow();
    this.probe();
    const api = {
      seek: (t) => { this.pause(); this.frozen = true; this.render(+t, true); return this.t; },
      play: () => this.play(), pause: () => this.pause(), load: (s) => this.load(s), begin: () => this.begin(),
      get t() { return api._t(); }, _t: () => this.t,
      duration: this.duration, chapters: this.chapters.map((c) => ({ t: c.start, n: c.n, title: c.title })), marks: this.marks,
      ready: (document.fonts ? document.fonts.ready : Promise.resolve()).then(() => new Promise((r) => requestAnimationFrame(() => { this.relayout(); r(true); }))),
    };
    this.api = api;
    if (!window.tour || o.global) window.tour = api;
    this.drivers();
    this.ro = new ResizeObserver(() => { clearTimeout(this.rz); this.rz = setTimeout(() => this.relayout(), 60); });
    this.ro.observe(this.stage);
    document.fonts?.ready.then(() => this.relayout());
  }

  $$(s) { return s ? [...this.win.querySelectorAll(sel(s))] : []; }
  one(s) { const e = this.$$(s)[0]; if (!e && s) console.warn('[tour] nothing matches', s); return e || null; }

  /* ── overlays the engine owns ── */
  overlays() {
    const mk = (cls, html = '', tag = 'div') => { const e = document.createElement(tag); e.className = cls; e.innerHTML = html; this.stage.append(e); return e; };
    this.card = mk('tour-card', '<span class="tour-card-n"></span><h3></h3><p></p>');
    this.cap = mk('tour-cap', '', 'p');
    this.keysEl = mk('tour-keys');
    this.rings = [mk('tour-ring'), mk('tour-ring'), mk('tour-ring')];
    this.cur = mk('tour-cur', CURSORS + '<span class="tour-touch"></span>');
    this.cur.dataset.look = this.root.dataset.cursorLook || 'dark';
    this.shapes = { arrow: this.cur.querySelector('.tour-arrow'), pointer: this.cur.querySelector('.tour-hand'), text: this.cur.querySelector('.tour-beam') };
    this.gates = [...this.root.querySelectorAll('[data-tour-gate]')];
    if (matchMedia('(hover: none)').matches) this.gates.forEach((g) => { const l = g.querySelector('[data-tour-gate-label]'); if (l) l.textContent = 'Tap to play'; });
  }

  /* ── compile the script into channels, a cursor track, zooms and overlays ── */
  compile() {
    const S = this.S;
    this.ch = []; this.chMap = new Map(); this.track = []; this.zooms = []; this.chapters = []; this.caps = []; this.keyList = [];
    this.ringAt = []; this.deferred = []; this.n = 0; this.marks = [];
    let clock = 0, last = 0, k = 0;
    for (const st of S.steps || []) {
      const start = st.at != null ? st.at : clock + (st.wait || 0);
      let end = start; k++;
      switch (st.do) {
        case 'pause': end = start + (st.dur ?? 1); break;
        case 'move': case 'hover': case 'click': case 'dblclick': case 'drag': case 'longpress': case 'swipe': {
          const el = this.one(st.do === 'drag' ? st.handle : st.do === 'swipe' ? st.on : st.to); const g = { kind: st.do, el, i: k, start, aim: st.aim || [.5 + (rnd(k) - .5) * .18, .55 + (rnd(k + 7) - .5) * .16], shape: st.cursor, who: st.by || 'main', from: st.from, tag: st.tag };
          g.arrive = start + (st.do === 'drag' || st.do === 'swipe' ? st.approach ?? (st.do === 'swipe' ? .7 : .8) : st.dur ?? .9);
          if (st.do === 'longpress') { const c0 = g.arrive + .06; g.act = c0 + (st.hold ?? .7); g.press = [[c0, g.act + (st.lift ?? .35)]]; g.end = g.act; this.ringAt.push({ t: g.act, g }); }
          if (st.do === 'swipe') this.swipeStep(st, g, el);
          if (st.do === 'move') g.end = g.arrive;
          if (st.do === 'hover') g.end = g.arrive + (st.hold ?? .6);
          if (st.do === 'click') { g.press = [[g.arrive + .06, g.arrive + .18]]; g.act = g.arrive + .18; g.end = g.act + .12; }
          if (st.do === 'dblclick') { const a = g.arrive; g.press = [[a + .06, a + .15], [a + .26, a + .35]]; g.act = a + .35; g.end = g.act + .15; }
          if (st.do === 'drag') {
            g.g0 = g.arrive + .22; g.g1 = g.g0 + (st.dur ?? 1.2); g.release = g.g1 + .1; g.end = g.release + .12;
            g.press = [[g.arrive + .08, g.release]]; g.act = g.release;
            const p = (t) => ease(cl((t - g.g0) / (g.g1 - g.g0)));
            if (st.prop) for (const e of st.el ? this.$$(st.el) : [el]) if (e) this.seg(e, st.prop, g.g0, (t) => lerp(st.from ?? 0, st.to ?? 1, p(t)));
            if (st.text) { const [ts, f] = st.text; for (const e of this.$$(ts)) this.seg(e, 'text', g.g0, (t) => f(lerp(st.from ?? 0, st.to ?? 1, p(t)))); }
            if (st.onto && el) { g.onto = this.one(st.onto); g.delta = [0, 0]; this.seg(el, 'translate', g.g0, (t) => [g.delta[0] * p(t), g.delta[1] * p(t)]); this.deferred.push({ t: g.arrive, run: () => this.measureDelta(g) }); }
          }
          if (g.press) for (const [a, b] of g.press) { if (el) { this.seg(el, 'class:is-press', a, () => true); this.seg(el, 'class:is-press', b, () => false); } }
          if (st.do === 'click' || st.do === 'dblclick') for (const [, b] of g.press) this.ringAt.push({ t: b, g });
          if (st.do === 'drag') this.ringAt.push({ t: g.press[0][0] + .1, g });
