/* demo/deck: the placeholder product inside every tour slide, in design pixels (1200 × 750).
   Replace this file with your product's own CSS when your screens go in (AGENT.md, step 2). Scoped to .demo-deck-app
   so it never meets another format's product on the same page. */
.demo-deck-app{--insp:0;position:relative;display:grid;grid-template-columns:212px minmax(0,1fr) calc(var(--insp) * 300px);background:var(--ph);
  font:400 13px/1.35 var(--sans);color:var(--ink);text-align:left;overflow:hidden;--line:var(--ph-line);--soft:var(--page)}
.demo-deck-app svg{width:16px;height:16px;flex:none;fill:none;stroke:currentColor;stroke-width:1.4;stroke-linecap:round;stroke-linejoin:round}
.demo-deck-app button{font:inherit;border:0;background:none;color:inherit;padding:0}
.demo-deck-app [data-tone="1"]{--tone:var(--ph)}.demo-deck-app [data-tone="2"]{--tone:var(--page-2)}.demo-deck-app [data-tone="3"]{--tone:var(--ink-2)}
.demo-deck-app [data-tone="4"]{--tone:var(--rule)}.demo-deck-app [data-tone="5"]{--tone:var(--ink)}

/* sidebar */
.demo-deck-app .app-side{display:flex;flex-direction:column;gap:6px;padding:16px 12px 14px;background:var(--soft);border-right:1px solid var(--line);min-width:0}
.demo-deck-app .app-ws{display:flex;align-items:center;gap:9px;padding:4px 8px 14px;font-weight:600}
.demo-deck-app .app-ws svg{margin-left:auto;color:var(--ink-3)}
.demo-deck-app .app-logo{width:22px;height:22px;border-radius:6px;background:var(--ink)}
.demo-deck-app .app-nav{display:grid;gap:2px}
.demo-deck-app .app-nav a{display:flex;align-items:center;gap:10px;padding:7px 8px;border-radius:6px;color:var(--ink-2);font-weight:500}
.demo-deck-app .app-nav a svg{color:var(--ink-3)}
.demo-deck-app .app-nav a.is-on{background:var(--ph);color:var(--ink);box-shadow:0 0 0 1px var(--line)}
.demo-deck-app .app-nav a.is-on svg{color:var(--ink)}
.demo-deck-app .app-label{margin:18px 8px 4px;font:500 11px/1 var(--sans);letter-spacing:.08em;text-transform:uppercase;color:var(--ink-3)}
.demo-deck-app .app-recent{display:grid;gap:2px}
.demo-deck-app .app-recent > span{display:flex;align-items:center;gap:10px;padding:7px 8px;color:var(--ink-2)}
.demo-deck-app .app-recent i{width:10px;height:10px;border-radius:3px;background:var(--line)}
.demo-deck-app .app-recent b{height:7px;width:var(--w);border-radius:4px;background:var(--line)}
.demo-deck-app .app-recent-new{--in:0;opacity:var(--in);margin-bottom:calc((var(--in) - 1) * 33px);font-weight:500;color:var(--ink)!important}
.demo-deck-app .app-recent-new i{background:var(--tone,var(--ink))!important;box-shadow:inset 0 0 0 1px var(--line)}
.demo-deck-app .app-me{margin-top:auto;display:flex;align-items:center;gap:10px;padding:10px 8px 0;border-top:1px solid var(--line)}
.demo-deck-app .app-me .ph{width:30px;flex:none}
.demo-deck-app .app-me b{display:block;font-weight:500}.demo-deck-app .app-me small{color:var(--ink-3);font-size:12px}

/* toolbar */
.demo-deck-app .app-main{position:relative;display:flex;flex-direction:column;min-width:0}
.demo-deck-app .app-bar{flex:none;height:60px;display:flex;align-items:center;gap:10px;padding:0 20px 0 26px;border-bottom:1px solid var(--line)}
.demo-deck-app .app-bar h4{margin:0 auto 0 0;display:flex;align-items:center;gap:9px;font:600 17px/1 var(--sans);letter-spacing:-.01em}
.demo-deck-app .app-count{min-width:22px;padding:4px 7px;border-radius:99px;background:var(--soft);box-shadow:inset 0 0 0 1px var(--line);font:500 11.5px/1 var(--sans);color:var(--ink-2);text-align:center}
.demo-deck-app .app-search{display:flex;align-items:center;gap:8px;width:200px;height:32px;padding:0 10px;border-radius:7px;box-shadow:inset 0 0 0 1px var(--line);color:var(--ink-3)}
.demo-deck-app .app-seg{display:flex;padding:3px;border-radius:8px;background:var(--soft);box-shadow:inset 0 0 0 1px var(--line);font-weight:500;color:var(--ink-3)}
.demo-deck-app .app-seg span{padding:6px 11px;border-radius:5px}
.demo-deck-app .app-seg .is-on{background:var(--ph);color:var(--ink);box-shadow:0 1px 2px rgba(25,24,22,.1),0 0 0 1px var(--line)}
.demo-deck-app .app-btn{display:inline-flex;align-items:center;gap:6px;height:32px;padding:0 13px;border-radius:7px;background:var(--ph);box-shadow:inset 0 0 0 1px var(--rule);font-weight:500;color:var(--ink);white-space:nowrap}
.demo-deck-app .app-btn.is-primary{background:var(--ink);color:var(--page);box-shadow:none}
.demo-deck-app .app-btn.is-hover{background:var(--soft)}
.demo-deck-app .app-btn.is-primary.is-hover{background:#000}
.demo-deck-app .is-press{transform:scale(.96)}

/* body: an empty state that fills in */
.demo-deck-app .app-body{position:relative;flex:1;min-height:0;padding:24px 26px}
.demo-deck-app .app-empty{--in:1;position:absolute;inset:24px 26px;display:grid;place-content:center;justify-items:center;gap:8px;border-radius:12px;border:1.5px dashed var(--rule);text-align:center;opacity:var(--in);transform:scale(calc(.98 + .02 * var(--in)))}
.demo-deck-app .app-empty-art{position:relative;width:96px;height:72px;margin-bottom:12px}
