.demo-deck-app .app-empty b{font:600 16px/1.2 var(--sans)}
.demo-deck-app .app-empty p{margin:0;color:var(--ink-3)}
.demo-deck-app .app-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px 20px}
.demo-deck-app .app-card{--in:0;position:relative;display:grid;gap:7px;padding:8px 8px 12px;border-radius:12px;opacity:var(--in);transform:translateY(calc((1 - var(--in)) * 14px))}
.demo-deck-app .app-card .app-cover{border-radius:8px;background:var(--tone,var(--ph))}
.demo-deck-app .app-card b{padding:2px 4px 0;font-weight:600}
.demo-deck-app .app-card small{padding:0 4px;color:var(--ink-3);font-size:12px}
.demo-deck-app .app-card > i{height:8px;width:var(--w);margin:6px 4px 2px;border-radius:4px;background:var(--rule)}
.demo-deck-app .app-bars{display:flex;gap:6px}.demo-deck-app .app-bars i{height:6px;width:56px;border-radius:3px;background:var(--line)}.demo-deck-app .app-bars i+i{width:34px}
.demo-deck-app .app-card.is-hover{background:var(--soft)}
.demo-deck-app .app-card.is-sel{background:var(--soft);box-shadow:0 0 0 1.5px var(--ink)}
.demo-deck-app .app-badge{position:absolute;right:16px;top:16px;padding:4px 7px;border-radius:5px;background:var(--ink);color:var(--page);font:600 10.5px/1 var(--sans);font-style:normal;letter-spacing:.04em;text-transform:uppercase}

/* the room: a project opened full size, growing out of the first card */
