  clip-path:inset(calc((1 - var(--open)) * 24px) calc((1 - var(--open)) * (100% - 26px - (100% - 92px) / 3)) calc((1 - var(--open)) * (100% - 278px)) calc((1 - var(--open)) * 26px) round calc(12px - var(--open) * 12px));
  opacity:min(1,calc(var(--open) * 6));pointer-events:none}
.demo-deck-app .app-room-bar{flex:none;display:flex;align-items:center;gap:10px;height:54px;padding:0 26px;border-bottom:1px solid var(--line);opacity:calc(var(--open) * 2 - 1)}
.demo-deck-app .app-room-bar b{font:600 15px/1 var(--sans)}
.demo-deck-app .app-tabs{margin-left:auto;display:flex;gap:4px;color:var(--ink-3);font-weight:500}
.demo-deck-app .app-tabs span{padding:7px 11px;border-radius:6px}.demo-deck-app .app-tabs .is-on{color:var(--ink);background:var(--soft)}
.demo-deck-app .app-room-scroll{flex:1;min-height:0;overflow:hidden;padding:22px 26px 40px}
