.demo-deck-app .app-room-cols{display:grid;grid-template-columns:1fr 1.15fr;gap:28px}
.demo-deck-app .app-h{margin:0 0 10px;font:500 11px/1 var(--sans);letter-spacing:.08em;text-transform:uppercase;color:var(--ink-3)}
.demo-deck-app .app-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
.demo-deck-app .app-stats > span{position:relative;display:grid;gap:8px;align-content:start;padding:14px;border-radius:10px;box-shadow:inset 0 0 0 1px var(--line);height:150px}
